  "termsScreen": {
    "paragraph1": "Бо истифодаи Sabi шумо розӣ мешавед, ки қоидаҳои платформа, қонунгузории амалкунанда ва талаботи амниятиро, ки барои истифодаи функсияҳои ҳамён, иртибот, муомилот ва хизматрасониҳои рақамӣ муқаррар шудаанд, риоя намоед.",
    "paragraph2": "Истифодабаранда барои дурустии маълумоти пешниҳодшуда, ҳифзи дастгоҳҳои худ, назорати дастрасӣ ба ҳисоб ва қонуниятии амалҳое, ки дар низом анҷом дода мешаванд, масъул аст.",
    "paragraph3": "Sabi метавонад барои беҳтар кардани маҳсулот, мутобиқат ба талаботи танзимкунанда ва ҳифзи истифодабарандагон функсионал, талаботи амниятӣ, қоидаҳои истифода ва шартҳои алоҳидаи хизматрасониро нав намояд.",
    "paragraph4": "Идомаи истифодаи платформа баъд аз навсозии шартҳо маънои розигӣ бо таҳрири амалкунандаи қоидаҳои хизматрасониро дорад.",
  },
  "privacyPolicyScreen": {
    "paragraph1": "Sabi foydalanuvchilarning maxfiyligini hurmat qiladi va shaxsiy ma’lumotlarni himoya qiladi. Biz telefon raqami, qurilma ma’lumotlari, texnik jurnallar va ro‘yxatdan o‘tish, akkaunt xavfsizligi, shaxsni tasdiqlash, firibgarlikning oldini olish va xizmatni yaxshilash uchun zarur bo‘lgan boshqa ma’lumotlarni yig‘ishimiz mumkin.",
    "paragraph2": "Sizning ma’lumotlaringiz faqat platforma ishlashi, qonunchilikka rioya qilish, tranzaksiyalarni himoya qilish, foydalanuvchilarni qo‘llab-quvvatlash va SuperApp funksiyalarini rivojlantirish doirasida ishlatiladi.",
    "paragraph3": "Biz shaxsiy ma’lumotlarni qonuniy asoslarsiz uchinchi tomonga oshkor qilmaymiz, bundan xizmat ko‘rsatish, verifikatsiya jarayoni, normativ talablarni bajarish yoki foydalanuvchilar hamda platforma huquqlari va xavfsizligini himoya qilish talab etiladigan holatlar mustasno.",
    "paragraph4": "Sabi’dan foydalanish orqali siz ushbu siyosatga muvofiq ma’lumotlar qayta ishlanishiga rozilik bildirasiz.",
  },
